-- Analytics FC — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'analyticsfc.co.uk' OR LOWER(`name`) = LOWER('Analytics FC'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Analytics FC', NULL, 'https://analyticsfc.co.uk', NULL, NULL, 'Спортивна консалтингова компанія на основі даних: платформа скаутингу з даними, консультації щодо трансферів і контрактів, підбір головного тренера, інтеграція алгоритмів у системи клубів і безкоштовна перевірка трансферів.', 'A data-driven sports consultancy: a data scouting platform, transfer and contract advisory, head coach search, algorithm integration into club systems and a free transfer eligibility check.', 'Analytics FC — консалтингова компанія у футболі, яка поєднує аналітику результатів і бізнес-підхід, допомагаючи гравцям, клубам, федераціям і агентствам досягати стратегічних цілей. Компанія створює індивідуальні моделі даних під потреби клієнтів, а досвідчені фахівці інтерпретують дані й допомагають ухвалювати розумніші рішення. Серед послуг — платформа скаутингу з даними для пошуку гравців по всьому світу, консультації щодо трансферів і контрактів, що поєднують футбольне розуміння й бізнес-аналітику, та сервіс профілювання й пошуку головного тренера для власників і керівників клубів. Алгоритми можна інтегрувати безпосередньо у власні технологічні системи. Є безкоштовний застосунок для перевірки, чи відповідають цілі трансферу вимогам для британського ринку, а також консультації для інвесторів щодо можливостей і ризиків.', 'Analytics FC is a football consultancy that fuses performance analytics with business acumen to help players, clubs, federations and agencies achieve their strategic goals. The company builds customized data models around client needs, and experienced specialists interpret the data to support smarter decisions. Services include a data scouting platform to scout players worldwide, transfer and contract advisory combining football insight with business analytics, and a data-driven head coach profiling and search service for owners and executives. Its algorithms can be integrated directly into your own technology systems. There is a free app to check whether transfer targets are eligible for the UK market, as well as advisory for investors on opportunities and risks.', 'Платформа скаутингу з даними
Консультації щодо трансферів і контрактів
Пошук і профілювання головного тренера
Інтеграція алгоритмів у системи клубу
Безкоштовна перевірка трансферів для Британії
Консультації для інвесторів', 'Data scouting platform
Transfer and contract advisory
Head coach search and profiling
Algorithm integration into club systems
Free UK transfer eligibility check
Investor advisory', 'Футбольні клуби, федерації, агентства, гравці й інвестори у футбол.', 'Football clubs, federations, agencies, players and investors in football.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
