-- Ballogy — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'ballogy.com' OR LOWER(`name`) = LOWER('Ballogy'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Ballogy', NULL, 'https://ballogy.com', NULL, NULL, 'Застосунок, який перетворює зусилля спортсменів на дані, а дані — на розвиток: відстеження руху, тренувань і відновлення для гравців, AI-інструменти для тренерів і команд, а також рішення для спортивних таборів.', 'An app that turns athletes'' effort into data and data into development: tracking movement, training and recovery for players, AI tools for coaches and teams, and solutions for sports camps.', 'Ballogy допомагає спортсменам, тренерам і командам будь-якого рівня перетворювати зусилля на дані, а дані — на розвиток. Спортсмени відстежують, як рухаються, тренуються й відновлюються, і вибудовують звички, що відрізняють хороших гравців від видатних. Для тренерів і команд є інструменти зі штучним інтелектом для розумнішого планування тренувань, розвитку гравців і керування командою в одному місці: можна призначати тренування, переглядати результати, аналізувати статистику ігор і стежити за прогресом команди за допомогою AI-помічника Ballogy. Директори спортивних таборів отримують усе необхідне на будь-якому пристрої: сесії, відмітки присутності, таблиці лідерів і звіти для батьків. Для команд є безкоштовний план і платні плани залежно від кількості гравців; є також шкільна програма.', 'Ballogy helps athletes, coaches and teams at every level turn effort into data and data into development. Athletes track how they move, train and recover and build the habits that separate good athletes from great ones. Coaches and teams get AI-powered tools for smarter practice planning, player development and team management in one place: assign workouts, review performance, analyze box scores and follow team progress with the Ballogy AI Assistant. Camp directors get everything they need on any device: sessions, attendance, leaderboards and parent reports. Teams have a free plan and paid plans based on roster size, and there is a school program.', 'Відстеження руху, тренувань і відновлення
AI-помічник Ballogy
Планування тренувань і розвиток гравців
Аналіз статистики ігор
Огляд прогресу команди
Інструменти для спортивних таборів', 'Movement, training and recovery tracking
Ballogy AI Assistant
Practice planning and player development
Box score analysis
Team progress overview
Tools for sports camps', 'Спортсмени, тренери шкільних і клубних команд, директори спортивних таборів.', 'Athletes, school and club team coaches, sports camp directors.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
