INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Since 2021, Bolt6 has been building technology that improves the experience of sport for everyone: officiating, athlete performance, the fan experience and commercial results for competition organizers. Optical tracking is at the core: the system tracks the ball, players and even cars in real time, with accuracy validated using VICON technology and reliability of about 99.9%. Sentinel is a real-time officiating system officially approved for international tennis and volleyball and the only officially approved cloud-based technology of its kind. Shotlink 2.0 is the optical tracking technology behind the reimagined PGA Tour data collection. Bolt6 also offers video replay systems and broadcast graphics.', 'manual' FROM DUAL WHERE @new = 1;
