-- Driblab — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'driblab.com' OR LOWER(`name`) = LOWER('Driblab'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Driblab', NULL, 'https://driblab.com', NULL, NULL, 'Футбольна аналітика й скаутинг на основі великих даних в одному місці: рішення, адаптовані під кожного клієнта, передові алгоритми й продукти на кшталт Driblab XY для аналізу даних, доступні як онлайн-сервіс або через API.', 'Big-data football analytics and scouting in one place: client-tailored solutions, cutting-edge algorithms and products such as Driblab XY for data analysis, available as a SaaS or via API.', 'Driblab допомагає всім професіоналам футбольної індустрії ухвалювати кращі рішення завдяки інтелектуальним даним і позиціонує себе як універсальне рішення для даних і скаутингу. Компанія працює як союзник фахівців: тісно співпрацює з кожним клієнтом і адаптує аналітику під його задачі. Усі потреби в даних можна закрити в одного постачальника — у форматі онлайн-сервісу або через API. Driblab постійно запускає нові продукти на основі складних алгоритмів, щоб кожна секунда матчу мала своє рішення у даних. Наприклад, Driblab XY пропонує поглиблений аналіз даних для професіоналів футболу. Аналітика зменшує ризик помилок і економить клубам час і гроші, допомагаючи випереджати суперників. Доступна демонстрація.', 'Driblab helps every professional in the football industry make better decisions through intelligent data and describes itself as a one-stop shop for data and scouting. The company acts as an ally to professionals: it works closely with each client and adapts its analytics to their specific needs. All data needs can be covered by one provider, delivered via SaaS or API. Driblab keeps launching new products built on complex algorithms so that every second of a game has a data solution. For example, Driblab XY offers advanced data analysis for football professionals. The analytics reduce the margin of error and save clubs time and money, helping them get ahead of rivals. Demos are available.', 'Футбольна аналітика на основі великих даних
