SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'eyeball.club' OR LOWER(`name`) = LOWER('Eyeball'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Eyeball', NULL, 'https://eyeball.club', NULL, NULL, 'Платформа для дитячо-юнацького футболу, яка об''єднує гравців, тренерів, батьків, скаутів, академії й федерації: аналіз виступів і супровід розвитку гравців, пошук талантів і система відстеження юних гравців у масштабі країни.', 'A youth football platform connecting players, coaches, parents, scouts, academies and federations: performance analysis and guided player development, talent discovery and nationwide youth player tracking.', 'Eyeball — операційна система для дитячо-юнацького футболу, побудована на ідеї, що видимість створює можливості, але бути поміченим — це ще й бути зрозумілим. Платформа пропонує окремі можливості для кожної ролі. Гравці краще розуміють свої виступи й отримують підказки для розвитку. Тренери працюють ефективніше й економлять час. Батьки більше бачать і розуміють футбольний шлях дитини. Скаути шукають талановитих юних гравців. Федерації можуть будувати загальнонаціональну систему відстеження юних гравців, академії — отримати операційну систему з усім необхідним, ліги — додати своїм змаганням нової цінності, а аматори — доступ до аналізу професійного рівня. Платформа відстежує сотні тисяч юних гравців у більш ніж 40 країнах і пов''язана з тисячами професійних клубів.', 'Eyeball is an operating system for youth football built on the idea that visibility creates opportunity, but being seen also means being understood. The platform offers dedicated features for each role. Players understand their performance better and get guided development help. Coaches work more effectively and save time. Parents see and understand more of their child''s football journey. Scouts find talented young players. Federations can build a nationwide youth tracking system, academies get an operating system with everything they need, leagues add new value to their competitions, and amateurs get access to pro-level analysis. The platform tracks hundreds of thousands of youth players across more than 40 countries and is connected to thousands of professional clubs.', 'Аналіз виступів юних гравців
Супровід розвитку гравців
Інструменти для тренерів
Пошук талантів для скаутів
Система відстеження гравців для федерацій
Операційна система для академій', 'Youth player performance analysis
Guided player development
Tools for coaches
Talent discovery for scouts
Player tracking system for federations
Operating system for academies', 'Юні футболісти, їхні батьки, тренери, скаути, академії, ліги й федерації.', 'Young footballers, their parents, coaches, scouts, academies, leagues and federations.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
