SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'geniussports.com' OR LOWER(`name`) = LOWER('Genius Sports'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Genius Sports', NULL, 'https://geniussports.com', NULL, NULL, 'Технологічна платформа для спорту, яка поєднує глибоке розуміння гри й даних про вболівальників: аналітика даних і аналіз результатів для команд і ліг, інструменти для залучення вболівальників, контент наживо для правовласників і рішення для брендів.', 'A sports technology platform that combines deep understanding of the game with fan intelligence: data analytics and performance analysis for teams and leagues, fan engagement tools, live content for rights-holders and solutions for brands.', 'Genius Sports позиціонує себе як операційну систему сучасного спорту, що поєднує поглиблене розуміння гри з даними про вболівальників і змінює те, як спорт аналізують, показують і переживають. Командам і лігам компанія пропонує нові способи розвивати й утримувати аудиторію, аналітику спортивних даних і аналіз результатів. Власники контенту можуть доповнювати трансляції даними в реальному часі. Брендам Genius Sports допомагає залучати вболівальників через креатив, медіазакупівлю, гейміфікацію й спортивні технології — наприклад, створювати рекламу з живими рахунками й статистикою матчів. Компанія також надає букмекерським операторам дані, алгоритми й інструменти керування ризиками.', 'Genius Sports describes itself as the operating system of modern sport, combining an advanced understanding of the game with deep fan intelligence to transform how sports are analyzed, seen and enjoyed. For teams and leagues it offers new ways to grow and own their fanbase, sports data analytics and performance analysis. Content owners can augment broadcasts with real-time data. For brands, Genius Sports drives fan engagement through creative, sports-centric media buying, gamification and sports technology, for example ads built on live scores and match stats. The company also provides sportsbook operators with data, algorithms and risk management tools.', 'Аналітика спортивних даних для команд і ліг
