-- Hawk-Eye — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hawkeyeinnovations.com' OR LOWER(`name`) = LOWER('Hawk-Eye'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hawk-Eye', NULL, 'https://hawkeyeinnovations.com', NULL, NULL, 'Технології для спорту: точне оптичне відстеження м''яча й гравців, багаторакурсний відеоповтор для суддівства, системи VAR і рішення для телетрансляцій. Використовуються в 25 видах спорту на змаганнях у понад 100 країнах.', 'Technology for sport: precise optical ball and player tracking, multi-angle video replay for officiating, VAR systems and broadcast solutions. Used across 25 sports at events in more than 100 countries.', 'Hawk-Eye змінює спорт за допомогою технологій точного відстеження, сучасних трансляцій і суддівства. Усі рішення компанії побудовані на трьох ключових технологіях. Відеоповтор із кількох ракурсів забезпечує запис, перегляд і нарізку відео — це основа систем перегляду спірних моментів і VAR. Оптичне відстеження й калібрування камер дозволяють точно відстежувати м''яч, гравців та інші об''єкти й аналізувати результати. Аналітичні інструменти перетворюють ці дані на висновки. Технології Hawk-Eye використовують у 25 провідних видах спорту — футболі, тенісі, крикеті, бейсболі, баскетболі, регбі, гольфі та інших — на турнірах і в лігах світового рівня. Компанія, зокрема, допомагала модернізувати суддівство й інфраструктуру грецького футболу, а система SkeleTRACK перетворює дані про рухи бейсболістів на контент для вболівальників.', 'Hawk-Eye transforms sport with precision tracking, immersive broadcast and officiating technology. All of its solutions are built on three core technologies. Multi-angle video replay powers video capture, review and clipping and underpins review and VAR systems. Optical tracking and camera calibration enable precise tracking of the ball, players and other objects and support performance analysis. Insight tools turn this data into conclusions. Hawk-Eye technology is used in 25 top sports, including football, tennis, cricket, baseball, basketball, rugby and golf, at world-class tournaments and leagues. The company has, for example, helped modernize officiating and infrastructure in Greek football, and SkeleTRACK turns baseball movement data into fan engagement content.', 'Багаторакурсний відеоповтор
Системи суддівства й VAR
Оптичне відстеження м''яча й гравців
Калібрування камер
Аналітика результатів
Рішення для телетрансляцій', 'Multi-angle video replay
Officiating and VAR systems
Optical ball and player tracking
