INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Hawk-Eye transforms sport with precision tracking, immersive broadcast and officiating technology. All of its solutions are built on three core technologies. Multi-angle video replay powers video capture, review and clipping and underpins review and VAR systems. Optical tracking and camera calibration enable precise tracking of the ball, players and other objects and support performance analysis. Insight tools turn this data into conclusions. Hawk-Eye technology is used in 25 top sports, including football, tennis, cricket, baseball, basketball, rugby and golf, at world-class tournaments and leagues. The company has, for example, helped modernize officiating and infrastructure in Greek football, and SkeleTRACK turns baseball movement data into fan engagement content.', 'manual' FROM DUAL WHERE @new = 1;
