SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'refsix.com' OR LOWER(`name`) = LOWER('REFSIX'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'REFSIX', NULL, 'https://refsix.com', NULL, NULL, 'Застосунок для футбольних арбітрів на смартгодиннику: таймери матчу, запис карток, голів і замін, автоматичний звіт про матч, а також точне вимірювання дистанції, теплова карта позиціонування й швидкість арбітра.', 'A smartwatch app for football referees: match timers, logging cards, goals and substitutions, an automatic match report, plus accurate distance, a positioning heatmap and referee speed.', 'REFSIX — застосунок для футбольних арбітрів, який замінює блокнот і відстежує їхню роботу на полі. На смартгодиннику легко фіксувати ключові епізоди матчу просто під час гри: стежити за часом за допомогою кількох таймерів — прямого, зворотного й еліптичного, записувати попередження й вилучення з номером гравця та причиною для автоматичного звіту про матч, відмічати голи й авторів, керувати замінами, відстежувати тимчасові вилучення й отримувати сповіщення, коли гравець може повернутися на поле. Окрім цього, REFSIX вимірює специфічні для арбітрів показники, що допомагають покращувати позиціонування й ухвалення рішень: точніше за звичайні фітнес-застосунки рахує пройдену дистанцію, будує теплову карту й показує швидкість протягом гри. Версія REFSIX PRO додає інструмент відеоаналізу. Застосунок працює на Apple Watch, Samsung, Garmin і годинниках з Wear OS.', 'REFSIX is an app for football referees that replaces the notebook and tracks their performance on the pitch. On a smartwatch they can easily record key incidents as they happen: keep track of time with multiple timers, count up, count down and elliptical, record cautions and dismissals with the player and reason for an automated match report, log goals and scorers, manage substitutions, and track sin bins with a notification when the player can return. REFSIX also measures referee-specific data that helps improve positioning and decision-making: it measures distance covered more accurately than typical fitness apps, builds a heatmap and shows speed during the game. REFSIX PRO adds a video analysis tool. The app runs on Apple Watch, Samsung, Garmin and Wear OS watches.', 'Кілька таймерів матчу
Запис карток, голів і замін
Автоматичний звіт про матч
Відстеження тимчасових вилучень
Дистанція, теплова карта й швидкість арбітра
Відеоаналіз у версії PRO
Apple Watch, Samsung, Garmin, Wear OS', 'Multiple match timers
Logging cards, goals and substitutions
Automatic match report
Sin bin tracking
Referee distance, heatmap and speed
Video analysis in PRO
Apple Watch, Samsung, Garmin, Wear OS', 'Футбольні арбітри будь-якого рівня — від аматорських ліг до професійних.', 'Football referees of every level, from amateur leagues to professionals.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
