SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'scisports.com' OR LOWER(`name`) = LOWER('SciSports'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SciSports', NULL, 'https://scisports.com', NULL, NULL, 'Програма аналізу футболу на основі даних: аналіз матчів для тренерів і аналітиків, скаутинг для скаутів і агентів, профілі гравців для дитячо-юнацьких програм. Обробляє понад 10 000 матчів на рік з оптичним відстеженням.', 'Data-driven football analysis software: match analysis for coaches and analysts, scouting for scouts and agents, and player profiles for youth programs. It processes more than 10,000 matches a year with optical tracking.', 'SciSports поєднує дані й емоції футболу, перетворюючи висновки на результат для гравців, клубів і ліг. Компанія використовує власні моделі штучного інтелекту й хмарні рішення, збирає, агрегує й візуалізує дані, а її системи працюють з будь-яким відеоджерелом і легко інтегрують зовнішні дані. Рішення розраховані на три аудиторії: аналіз матчів для тренерів і аналітиків, скаутинг для скаутів і агентів та профілі гравців для дитячо-юнацького розвитку. SciSports щороку обробляє понад 10 000 матчів по всьому світу, фіксуючи мільйони точок даних за матч за допомогою оптичного відстеження, і дозволяє аналізувати 150 подій із м''ячем для кожного гравця, команди чи матчу. Скаутингове рішення містить профілі сотень тисяч професійних гравців. Серед клієнтів — професійні клуби, ліги й академії.', 'SciSports blends data with the emotion of football, turning insight into impact for players, clubs and leagues. The company uses proprietary AI models and cloud solutions, captures, aggregates and visualizes data, and its systems work with any video source and integrate external data with minimal setup. Solutions serve three audiences: match analysis for coaches and analysts, scouting for scouts and agents, and player profiles for youth development. SciSports processes more than 10,000 matches a year worldwide, capturing millions of data points per match with optical tracking, and allows analysis of 150 on-ball events per player, team or match. The scouting solution profiles hundreds of thousands of professional players. Clients include pro clubs, leagues and academies.', 'Аналіз матчів для тренерів
Скаутинг для скаутів і агентів
Профілі гравців для юнацьких програм
Оптичне відстеження матчів
150 подій із м''ячем для аналізу
Робота з будь-яким відеоджерелом', 'Match analysis for coaches
Scouting for scouts and agents
Player profiles for youth programs
Optical match tracking
150 on-ball events to analyze
Works with any video source', 'Футбольні клуби, ліги, академії, тренери, аналітики, скаути й агенти.', 'Football clubs, leagues, academies, coaches, analysts, scouts and agents.', 'web', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
