Mobile app', 'Скаутингові відділи й керівники відбору гравців у футбольних клубах.', 'Scouting departments and heads of recruitment at football clubs.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
