SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'shottracker.com' OR LOWER(`name`) = LOWER('ShotTracker'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ShotTracker', NULL, 'https://shottracker.com', NULL, NULL, 'AI-інструменти для баскетболу: відстеження кожного кидка й руху на майданчику, відео, статистика й аналітика для тренерів, голосовий AI-помічник для скаутингу та рішення для залучення вболівальників і трансляцій.', 'AI tools for basketball: tracking every shot and move on the court, video, stats and analytics for coaches, a voice-activated AI scouting assistant and solutions for fan engagement and coverage.', 'ShotTracker — набір інструментів на основі відео, даних і штучного інтелекту, які допомагають підвищувати результати баскетбольних команд і залучати вболівальників. Система фіксує кожну деталь на майданчику — кидки, влучання й рухи гравців — за принципом «що вимірюється, тим можна опанувати». Розширена лінійка дозволяє обрати потрібне рішення: від аналітики елітного рівня до простих інструментів для швидкого старту. Coaching Stack об''єднує п''ять продуктів в одну екосистему, щоб тренери отримували швидші відповіді, кращі висновки й економили час. AI-помічник для скаутингу керується голосом. Крім тренерських задач, інструменти допомагають створювати контент і висвітлювати матчі. Для команд доступна демонстрація.', 'ShotTracker is a suite of video, data and AI tools that improve basketball team performance and fan engagement. The system captures every detail on the court, including shots, makes and player movement, on the principle that what gets measured gets mastered. An expanded lineup lets you pick the right fit, from elite-level analytics to quick-start tools. The Coaching Stack brings five products into one connected ecosystem so coaches get faster answers, better insights and time back in their day. The AI scouting assistant is voice-activated. Beyond coaching, the tools support content creation and game coverage. Teams can schedule a demo.', 'Відстеження кидків і рухів на майданчику
Відео, статистика й аналітика
Coaching Stack із п''яти продуктів
Голосовий AI-помічник для скаутингу
Інструменти для контенту й трансляцій
Рішення для залучення вболівальників', 'Shot and movement tracking on the court
Video, stats and analytics
Coaching Stack of five products
Voice-activated AI scouting assistant
Tools for content and coverage
Fan engagement solutions', 'Баскетбольні команди, тренери, ліги й медіа — від шкільного до професійного рівня.', 'Basketball teams, coaches, leagues and media, from high school to pro level.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
