SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportmonks.com' OR LOWER(`name`) = LOWER('Sportmonks'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sportmonks', NULL, 'https://sportmonks.com', NULL, NULL, 'API спортивних даних для розробників: рахунки наживо, статистика, склади, очікувані голи, прогнози й інші дані для футболу понад 2200 ліг, крикету й Формули-1 в одному REST API. Є безкоштовний план і швидкий старт.', 'A sports data API for developers: live scores, stats, lineups, expected goals, predictions and more for football across 2,200+ leagues, cricket and Formula 1 in one REST API, with a free plan and quick start.', 'Sportmonks — API спортивних даних для розробників, які створюють спортивні застосунки й сайти. Через один REST API доступні дані для футболу, крикету й Формули-1. Football API охоплює понад 2200 ліг: рахунки наживо, події матчу, склади, статистика, очікувані голи, прогнози та коефіцієнти — увесь матч-центр можна побудувати одним запитом. Cricket API дає рахунки наживо, дані про кожну подачу, картки бетсменів і боулерів та склади в єдиному JSON-форматі — від тест-матчів до ліг T20. Також є Formula One API. Сервіс обіцяє налаштування за кілька хвилин, безкоштовний план для старту, 14-денний пробний період для кожного тарифу та роботу без контрактів і мінімальних зобов''язань. Є документація й інтерактивні приклади відповідей.', 'Sportmonks is a sports data API for developers building sports apps and websites. One REST API covers football, cricket and Formula 1. The Football API covers more than 2,200 leagues with live scores, match events, lineups, stats, expected goals, predictions and odds, so a whole match centre can be built from one API call. The Cricket API provides live scores, ball-by-ball data, batting and bowling cards and lineups in one uniform JSON, from Test matches to T20 leagues. There is also a Formula One API. Setup takes minutes, there is a free plan to start, a 14-day trial on every plan, and no contracts or minimums. Documentation and interactive response examples are available.', 'Football API для понад 2200 ліг
Cricket API з даними про кожну подачу
