SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportsdata.io' OR LOWER(`name`) = LOWER('SportsDataIO'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SportsDataIO', NULL, 'https://sportsdata.io', NULL, NULL, 'Постачальник спортивних даних у реальному часі: рахунки, статистика, прогнози, новини й зображення для NFL, MLB, NBA, NHL, гольфу, NASCAR, тенісу, футболу й кіберспорту через API, віджети й прогностичні рушії.', 'A real-time sports data provider: scores, stats, projections, news and images for the NFL, MLB, NBA, NHL, golf, NASCAR, tennis, soccer and esports via APIs, widgets and predictive engines.', 'SportsDataIO — постачальник спортивних даних і контенту, який щороку генерує мільйони точок даних із тисяч ігор. Компанія ліцензує свої продукти через надійні API, адаптивні віджети й візуалізації та прогностичні рушії, щоб поширювати точну інформацію в реальному часі у зручних форматах корпоративного рівня. Дані охоплюють американський футбол NFL, бейсбол MLB, баскетбол NBA, хокей NHL, гольф PGA, NASCAR, теніс, футбол і кіберспорт. Серед продуктів — основний API спортивних даних, API для фентезі-спорту й коефіцієнтів, новини й зображення, а також віджети для відображення: інформаційні плитки, інтерактивні інструменти, огляди матчів і бігучі рядки та адміністративні панелі. Даними користуються медіа, гральні компанії та інші сектори; є безкоштовна пробна версія API.', 'SportsDataIO is a sports data and content provider producing millions of data points across thousands of games every year. It licenses its products through robust APIs, responsive widgets and visualizations, and predictive engines, distributing accurate information in real time in easy-to-use, enterprise-grade formats. Coverage includes NFL football, MLB baseball, NBA basketball, NHL hockey, PGA golf, NASCAR, tennis, soccer and esports. Products include a core sports data API, fantasy sports and odds APIs, news and images, plus display widgets such as content tiles, interactive tools, matchups and tickers, and admin dashboards. Media, gaming companies and other sectors use the data, and there is a free API trial.', 'Спортивні дані в реальному часі через API
NFL, MLB, NBA, NHL, гольф, NASCAR, теніс, футбол, кіберспорт
Прогностичні рушії
