SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'statmuse.com' OR LOWER(`name`) = LOWER('StatMuse'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'StatMuse', NULL, 'https://statmuse.com', NULL, NULL, 'Пошуковик спортивної статистики зі штучним інтелектом: миттєві відповіді на запитання про NBA, NFL, MLB, NHL, футбол, WNBA, гольф і студентський спорт звичайною мовою, рахунки, новини, тренди й доступ через API та MCP.', 'An AI search engine for sports stats: instant plain-language answers about the NBA, NFL, MLB, NHL, football, WNBA, golf and college sports, plus scores, news, trends and access via API and MCP.', 'StatMuse дає миттєві відповіді на запитання про спортивну статистику, сформульовані звичайною мовою. Достатньо запитати, і сервіс знайде потрібні цифри щодо NBA, NFL, MLB, NHL, футболу, WNBA, PGA та студентського американського футболу. На головній сторінці — добірки свіжої статистики про гравців і матчі, рахунки, новини й трендові запити. Окремий розділ Money присвячений фінансовим даним. Для розробників доступні API та MCP, тож дані й пошук StatMuse можна підключати до власних застосунків і AI-асистентів. Є також галерея прикладів, глосарій даних, блог і мобільний застосунок. Пошук корисний аналітикам, журналістам, тренерам і вболівальникам, яким потрібні точні цифри без ручного пошуку в таблицях.', 'StatMuse gives instant answers to sports statistics questions asked in plain language. Just ask, and it finds the numbers for the NBA, NFL, MLB, NHL, football, WNBA, PGA and college football. The home page features fresh stat highlights about players and games, scores, news and trending queries. A separate Money section covers financial data. Developers can use an API and MCP to connect StatMuse data and search to their own apps and AI assistants. There is also a gallery of examples, a data glossary, a blog and a mobile app. It is useful for analysts, journalists, coaches and fans who need accurate numbers without digging through tables.', 'Пошук статистики звичайною мовою
NBA, NFL, MLB, NHL, футбол, WNBA, PGA
