SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'statsbomb.com' OR LOWER(`name`) = LOWER('StatsBomb'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'StatsBomb', NULL, 'https://statsbomb.com', NULL, NULL, 'Детальні футбольні дані й аналітична платформа Hudl StatsBomb для професійних клубів: понад 3400 подій на матч у більш ніж 190 змаганнях і дані про розташування гравців для пошуку гравців, тактичного аналізу й оцінки результатів.', 'Detailed football data and the Hudl StatsBomb analysis platform for pro clubs: over 3,400 events per match across 190+ competitions plus player-location data for recruitment, tactical analysis and performance evaluation.', 'Hudl StatsBomb створює детальні футбольні дані для спільноти аналітиків і науковців з даних, допомагаючи професійним командам ухвалювати кращі рішення швидше. Дані використовують для пошуку й відбору гравців, тактичного аналізу й оцінки виступів. Компанія фіксує понад 3400 подій у кожному матчі в більш ніж 190 змаганнях і без доплати додає дані про розташування гравців для понад 40 провідних ліг. Дані збираються за допомогою штучного інтелекту й комп''ютерного зору, який розпізнає поле, а потім перевіряються, щоб забезпечити високу деталізацію, точність і послідовність. Окрім даних, є платформа для аналізу даних і відео, а також навчальні курси й блог. StatsBomb входить до екосистеми Hudl.', 'Hudl StatsBomb creates detailed football data for the data analysis and data science communities, helping professional teams make better decisions faster. The data powers player recruitment, tactical analysis and performance evaluation. The company captures more than 3,400 events per match across over 190 competitions and adds player-location data for more than 40 key leagues at no extra cost. Data is collected with AI and pitch-detection computer vision and then validated for high granularity, accuracy and consistency. Alongside the data there is an advanced data and video analysis platform, courses and a blog. StatsBomb is part of the Hudl ecosystem.', 'Понад 3400 подій у кожному матчі
Понад 190 змагань
Дані про розташування гравців
Платформа аналізу даних і відео
Підтримка пошуку й відбору гравців
Тактичний аналіз
Навчальні курси', '3,400+ events per match
190+ competitions
