SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'wingfield.io' OR LOWER(`name`) = LOWER('Wingfield'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Wingfield', NULL, 'https://wingfield.io', NULL, NULL, 'AI-камери для паделу, тенісу й пікболу: автоматичні хайлайти, миттєві повтори, прямі трансляції, ігрові тренувальні інструменти й аналітика для розвитку гравців, а для клубів — безкоштовний маркетинг через відео від гравців.', 'AI cameras for padel, tennis and pickleball: automatic highlights, instant replays, live streaming, gamified coaching tools and analytics for player development, plus free marketing for clubs through player-shared videos.', 'Wingfield створює AI-камери для ракеткових видів спорту — паделу, пікболу й тенісу, — які роблять більше, ніж просто записують і транслюють гру. Система автоматично створює хайлайти просто з кортів: найгарячіші розіграші перетворюються на відео, якими гравці діляться в соцмережах, і це безкоштовно поширює назву клубу, залучає нових учасників і зміцнює бренд. Відеорішення дають тренерам миттєві повтори для відеозворотного зв''язку, а аналітика й ігрові режими створюють захопливий процес навчання й допомагають гравцям реально прогресувати. Лінійка включає AI-камери для трансляцій, екрани на корті, застосунки й повні системи відстеження для аналітики. Наприклад, Cam+ пропонує синхронізацію із застосунком, миттєві повтори, прямі трансляції й автоматичні хайлайти. Ціни надаються за запитом.', 'Wingfield builds AI-powered cameras for racket sports, padel, pickleball and tennis, that go beyond standard recording and streaming. The system automatically creates highlight videos right from the courts: the hottest rallies become clips that players share on social media, spreading the club''s name, attracting new members and building its brand at no extra cost. Video tools give coaches instant replays for video feedback, while analytics and gameplay modes create engaging learning experiences that drive real player progress. The lineup includes AI streaming cameras, court screens, apps and full tracking systems for analytics. For example, Cam+ offers app synchronization, instant playback, live streaming and auto highlights. Prices are available on request.', 'AI-камери для паделу, тенісу й пікболу
Автоматичні хайлайти розіграшів
Миттєві повтори для тренерів
Прямі трансляції
Аналітика й ігрові тренувальні режими
Екрани на корті й застосунки', 'AI cameras for padel, tennis and pickleball
Automatic rally highlights
Instant replays for coaches
Live streaming
Analytics and gamified training modes
Court screens and apps', 'Клуби й академії паделу, тенісу й пікболу, тренери й гравці.', 'Padel, tennis and pickleball clubs and academies, coaches and players.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
