-- Wyscout — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hudl.com/products/wyscout' OR LOWER(`name`) = LOWER('Wyscout'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Wyscout', NULL, 'https://www.hudl.com/products/wyscout', NULL, NULL, 'Найбільша бібліотека футбольного відео й даних на одній платформі: записи й статистика з понад 1000 змагань, зона скаутингу, юнацькі турніри й дані для оцінки гравців ще до того, як відправити до них скаутів.', 'The biggest library of football video and data on one platform: footage and stats from more than 1,000 competitions, a scouting area, youth tournaments and data to evaluate players before sending scouts to watch them.', 'Hudl Wyscout — платформа аналітики футбольних даних із величезною бібліотекою відео й статистики з понад 1000 змагань у всьому світі. Вона допомагає ухвалювати рішення на основі доказів: можна відзначати потенційні цілі для трансферу й оцінювати їх за відео, перш ніж відправляти скаутів дивитися гравців наживо. Платформа включає зону скаутингу, окремі дані Wyscout і пакет юнацьких змагань з широким набором дитячо-юнацьких турнірів, зокрема ексклюзивних, щоб не пропустити наступну зірку й посилити програми скаутингу та розвитку гравців. Відео з Wyscout тепер миттєво переносяться в Hudl. Тарифи відрізняються обсягом перегляду кліпів і матчів, кількістю завантажень і даними; пакети можна налаштувати під потреби клубу, включно з доступом до API. Wyscout входить до екосистеми Hudl.', 'Hudl Wyscout is a football data analytics platform with a huge library of video and stats from more than 1,000 competitions worldwide. It supports evidence-based decisions: you can flag potential transfer targets and evaluate them through video before sending scouts to watch them live. The platform includes a scouting area, Wyscout Data and a Youth Competitions Pack with a wide range of youth tournaments, including exclusive ones, so you don''t miss the next breakthrough star and can strengthen scouting and player development programs. Wyscout videos now transfer to Hudl instantly. Plans differ by clip and match viewing time, downloads and data, and packages can be customized for a club, including API access. Wyscout is part of the Hudl ecosystem.', 'Відео й дані з понад 1000 змагань
Зона скаутингу
Оцінка гравців за відео до виїзду скаутів
Пакет юнацьких змагань
Статистика й дані Wyscout
Інтеграція з Hudl і доступ до API', 'Video and data from 1,000+ competitions
Scouting area
Evaluating players on video before sending scouts
Youth Competitions Pack
Wyscout stats and data
Hudl integration and API access', 'Футбольні клуби, скаути, агенти, аналітики й тренери.', 'Football clubs, scouts, agents, analysts and coaches.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
