INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Hudl Wyscout is a football data analytics platform with a huge library of video and stats from more than 1,000 competitions worldwide. It supports evidence-based decisions: you can flag potential transfer targets and evaluate them through video before sending scouts to watch them live. The platform includes a scouting area, Wyscout Data and a Youth Competitions Pack with a wide range of youth tournaments, including exclusive ones, so you don''t miss the next breakthrough star and can strengthen scouting and player development programs. Wyscout videos now transfer to Hudl instantly. Plans differ by clip and match viewing time, downloads and data, and packages can be customized for a club, including API access. Wyscout is part of the Hudl ecosystem.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'Video and data from 1,000+ competitions
Scouting area
