SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'zone14.ai' OR LOWER(`name`) = LOWER('zone14'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'zone14', NULL, 'https://zone14.ai', NULL, NULL, 'Повністю автоматичний відеоаналіз футболу для клубів: 180-градусна 4K-камера сама записує й транслює матчі без оператора, штучний інтелект визначає статистику гравців без трекерів, а інструменти позначок і малювання допомагають розбирати ключові моменти.', 'Fully automatic football video analysis for clubs: a 180-degree 4K camera records and streams matches with no operator, AI derives player stats without trackers, and tagging and drawing tools help break down key moments.', 'zone14 робить зйомку й відеоаналіз у футболі простими для клубів будь-якого рівня. Принцип — записати, транслювати, проаналізувати, перемогти. Камеру zone14 TWO з кутом огляду 180 градусів і роздільною здатністю 4K достатньо один раз встановити, далі штучний інтелект бере всю роботу на себе й автоматично записує кожну гру — оператор не потрібен. Сервіс zone14 REPLAY дозволяє аналізувати ключові моменти матчів і тренувань, ділитися ними для об''єктивних командних обговорень і покращувати гру; інструменти позначок і малювання роблять це простим і гнучким. zone14 LIVE транслює матчі для вболівальників і тренерів. Власний штучний інтелект визначає статистику гравців без апаратних трекерів. Рішенням користуються клуби різних ліг, зокрема в німецькомовних країнах.', 'zone14 makes filming and video analysis in football easy for clubs of any level. The principle is record, stream, analyze, win. The zone14 TWO camera, with a 180-degree view and 4K resolution, only needs to be set up once, after which AI takes over and records every game automatically, with no camera operator needed. zone14 REPLAY lets you analyze key moments from games and training, share them for objective team discussions and improve your play, and tagging and drawing tools make it simple and flexible. zone14 LIVE streams matches for fans and coaches. Proprietary AI derives player statistics without hardware trackers. Clubs across different leagues use it, particularly in German-speaking countries.', 'Автоматичний запис матчів 4K-камерою
